from PyQt6.QtCore import QEvent, Qt
from PyQt6.QtWidgets import QLabel


class QrPlacementOverlay(QLabel):
    """Draggable preview only; actual QR bytes are generated by the service."""
    def __init__(self, placement, options):
        super().__init__("QR\nDuplo clique\npara mover", placement)
        self.placement = placement
        self.options = options
        self._dragging = False
        self._unlocked = False
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setStyleSheet("background: white; color: #111827; border: 2px dashed #2563eb;")
        self.setToolTip("Prévia da área do QR. Dê duplo clique e arraste para ajustar.")
        placement.installEventFilter(self)
        for field in (options.x, options.y, options.size):
            field.valueChanged.connect(self.refresh)
        options.visible.toggled.connect(self.refresh)
        options.page.valueChanged.connect(self.refresh)
        self.refresh()

    def eventFilter(self, watched, event):
        if event.type() in (QEvent.Type.Resize, QEvent.Type.Show):
            self.refresh()
        return False

    def refresh(self, *_):
        page = self.placement._page_rect()
        width = getattr(self.placement, '_page_width', None)
        height = getattr(self.placement, '_page_height', None)
        if width is None:
            width, height = self.placement._page_size
            if self.placement._rotation in (90, 270):
                width, height = height, width
        self.setVisible(self.options.visible.isChecked())
        self.setGeometry(round(page.x() + self.options.x.value() / width * page.width()),
                         round(page.y() + self.options.y.value() / height * page.height()),
                         max(20, round(self.options.size.value() / width * page.width())),
                         max(20, round(self.options.size.value() / height * page.height())))
        self.raise_()

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.unlock()
            event.accept()

    def unlock(self):
        self._unlocked = True
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        self.setText("QR\nArraste para mover")

    def mousePressEvent(self, event):
        if self._unlocked and event.button() == Qt.MouseButton.LeftButton:
            self._dragging = True
            self._offset = event.position().toPoint()
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
            event.accept()

    def mouseMoveEvent(self, event):
        if not self._dragging:
            return
        point = self.mapToParent(event.position().toPoint()) - self._offset
        page = self.placement._page_rect()
        width = getattr(self.placement, '_page_width', None)
        height = getattr(self.placement, '_page_height', None)
        if width is None:
            width, height = self.placement._page_size
            if self.placement._rotation in (90, 270):
                width, height = height, width
        size = self.options.size.value()
        self.options.x.setValue(max(0, min((point.x()-page.x())/page.width()*width, width-max(size,120))))
        self.options.y.setValue(max(0, min((point.y()-page.y())/page.height()*height, height-size-27)))
        event.accept()

    def mouseReleaseEvent(self, event):
        self._dragging = False
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        event.accept()
